while (true) {

  let t10Closed = getTurnoutState(10);
  let t11Closed = getTurnoutState(11);
  let t12Closed = getTurnoutState(12);
  let t13Closed = getTurnoutState(13);

  // Signal #135
  if (!t10Closed && t11Closed) {
    await setSignalYellow(135);
  } else {
    await setSignalRed(135);
  }

  // Signal #120
  if (t10Closed && t11Closed) {
    await setSignalGreen(120);
  } else {
    await setSignalRed(120);
  }

  // Signal #140
  if (!t11Closed) {
    await setSignalYellow(140);
  } else {
    await setSignalRed(140);
  }

  // Signal #145
  if (!t12Closed) {
    await setSignalYellow(145);
  } else {
    await setSignalRed(145);
  }

  // Signal #150
  if (t12Closed && t13Closed) {
    await setSignalGreen(150);
  } else {
    await setSignalRed(150);
  }

  // Signal #155
  if (t12Closed && !t13Closed) {
    await setSignalYellow(155);
  } else {
    await setSignalRed(155);
  }

  await sleep(500);
}
